#!/bin/bash
# ALLINK: every INK_* variable is passed
# usage: run_ink.sh TAG IDS CTX NGEN [REF]   -- one run on gpu0 (03:00.0) only, container removed after.
X=/mnt/storage/isos/grimoire-runs/ink-1123
M=${MODEL:-/mnt/storage/Models/Inkling-2-Mini-Uncensored}
TAG=$1; shift; ARGS="$*"
if [ "${ALLOW_BUILD:-0}" != 1 ] && docker ps --format "{{.Names}}" | grep -v ink-1123-cpuref | grep -q .; then echo "OTHER CONTAINERS RUNNING"; docker ps; exit 1; fi
PCI=${INK_PCI:-0000:03:00.0}; N=$(readlink -f /dev/dri/by-path/pci-$PCI-render)
before=$(dmesg | grep -c "$PCI")
docker run -d --name ink-1123-$TAG --network none --device "$N:/dev/dri/renderD128" -v "$X:/work" -v "$M:/inkling:ro" -v /mnt/storage/Models/Inkling-2-Mini-DFlash2:/df2:ro -v /mnt/storage/isos/grimoire-runs/prof-1119/bin:/prof:ro \
  -e ONEAPI_DEVICE_SELECTOR=level_zero:0 -e UR_L0_ENABLE_RELAXED_ALLOCATION_LIMITS=1 -e INK_DEBUG=${INK_DEBUG:-0} ${INK_NOBIAS:+-e INK_NOBIAS=1} ${INK_POSSHIFT:+-e INK_POSSHIFT=$INK_POSSHIFT} ${INK_DUMP:+-e INK_DUMP=$INK_DUMP} ${INK_TAPMODE:+-e INK_TAPMODE=$INK_TAPMODE} ${INK_NOCTX:+-e INK_NOCTX=1} ${INK_SECT:+-e INK_SECT=1} ${INK_ESMOE:+-e INK_ESMOE=$INK_ESMOE} ${INK_NO_ATTES:+-e INK_NO_ATTES=1} ${INK_SM_LUT:+-e INK_SM_LUT=1} ${INK_SEG_NOWAIT:+-e INK_SEG_NOWAIT=1} ${INK_NORM_ROUTE:+-e INK_NORM_ROUTE=1} ${INK_SEP_ROUTE:+-e INK_SEP_ROUTE=1} ${INK_MIX_REGV:+-e INK_MIX_REGV=1} ${INK_SM_TNT:+-e INK_SM_TNT=$INK_SM_TNT} ${INK_XBF16:+-e INK_XBF16=1} ${INK_SEG_KCOPY:+-e INK_SEG_KCOPY=1} ${INK_I8M:+-e INK_I8M=$INK_I8M} ${INK_OLD_RESIDV:+-e INK_OLD_RESIDV=1} ${INK_SM_PF2:+-e INK_SM_PF2=1} ${INK_SEP_ADD:+-e INK_SEP_ADD=1} ${INK_DRAFT_FULL:+-e INK_DRAFT_FULL=1} ${INK_HV_NOK:+-e INK_HV_NOK=1} ${INK_HV_NOZ:+-e INK_HV_NOZ=1} ${INK_HV_NOY:+-e INK_HV_NOY=1} ${INK_SEP_HISTV:+-e INK_SEP_HISTV=1} ${INK_SEG_HOSTCOPY:+-e INK_SEG_HOSTCOPY=1} ${INK_SEG_SPIN:+-e INK_SEG_SPIN=1} ${INK_SEG_DIRECT:+-e INK_SEG_DIRECT=1} ${INK_SEG_NOSPIN:+-e INK_SEG_NOSPIN=1} ${INK_ROUTEGRP:+-e INK_ROUTEGRP=1} ${INK_NO_ROUTEGRP:+-e INK_NO_ROUTEGRP=1} ${INK_SEP_BIAS:+-e INK_SEP_BIAS=1} ${INK_ATT_CHUNK:+-e INK_ATT_CHUNK=$INK_ATT_CHUNK} ${INK_NO_BLENDE:+-e INK_NO_BLENDE=1} ${INK_SM_ILV:+-e INK_SM_ILV=1} ${INK_DRAFT_BF16:+-e INK_DRAFT_BF16=1} ${INK_NO_ATTSPLIT:+-e INK_NO_ATTSPLIT=1} ${INK_RMN:+-e INK_RMN=1} ${INK_NO_SEG:+-e INK_NO_SEG=1} ${INK_SM_KS:+-e INK_SM_KS=$INK_SM_KS} ${INK_OLD_ATTB:+-e INK_OLD_ATTB=1} ${INK_NO_EPREP:+-e INK_NO_EPREP=1} ${INK_DRAFT_OLD:+-e INK_DRAFT_OLD=1} ${INK_MTP_TIME:+-e INK_MTP_TIME=1} ${INK_OLD_BLEND:+-e INK_OLD_BLEND=1} ${INK_NO_GSMV:+-e INK_NO_GSMV=1} ${INK_OLD_GROUP:+-e INK_OLD_GROUP=1} ${INK_NO_I8V:+-e INK_NO_I8V=1} ${INK_SM_DBUF:+-e INK_SM_DBUF=1} ${INK_SM_NOPERM:+-e INK_SM_NOPERM=1} ${INK_SM_STAT:+-e INK_SM_STAT=1} ${INK_SM_WHOLE:+-e INK_SM_WHOLE=1} ${INK_NO_SMES:+-e INK_NO_SMES=1} ${INK_NO_MXES:+-e INK_NO_MXES=1} ${INK_NO_FUSEACT:+-e INK_NO_FUSEACT=1} ${INK_ATT_CMP:+-e INK_ATT_CMP=1} ${INK_ATT_TPW:+-e INK_ATT_TPW=$INK_ATT_TPW} ${INK_ATT_BK:+-e INK_ATT_BK=$INK_ATT_BK} ${INK_NO_NVES:+-e INK_NO_NVES=1} ${INK_NO_NVES:+-e INK_NO_NVES=1} ${INK_WO_TWICE:+-e INK_WO_TWICE=1} ${INK_ESI8:+-e INK_ESI8=$INK_ESI8} ${INK_ESI8O:+-e INK_ESI8O=$INK_ESI8O} ${INK_OLD_GATES:+-e INK_OLD_GATES=1} ${INK_OLD_ROUTE:+-e INK_OLD_ROUTE=1} ${INK_NO_RMN:+-e INK_NO_RMN=1} ${INK_IMATRIX:+-e INK_IMATRIX=$INK_IMATRIX} ${INK_KS_WP:+-e INK_KS_WP=$INK_KS_WP} ${INK_KS_WO:+-e INK_KS_WO=$INK_KS_WO} ${INK_ES_GU:+-e INK_ES_GU=$INK_ES_GU} ${INK_ES_DN:+-e INK_ES_DN=$INK_ES_DN} ${INK_I4:+-e INK_I4=$INK_I4} ${INK_I4_PARTS:+-e INK_I4_PARTS=$INK_I4_PARTS} ${GRIMOIRE_INT4_RTN_GROUP:+-e GRIMOIRE_INT4_RTN_GROUP=$GRIMOIRE_INT4_RTN_GROUP} ${GRIMOIRE_INT4_RTN_SEARCH:+-e GRIMOIRE_INT4_RTN_SEARCH=$GRIMOIRE_INT4_RTN_SEARCH} ${INK_GSM:+-e INK_GSM=$INK_GSM} ${L0V2:+-e SYCL_UR_USE_LEVEL_ZERO_V2=$L0V2} ${INK_XEXP:+-e INK_XEXP=$INK_XEXP} ${INK_XEXP_MODE:+-e INK_XEXP_MODE=$INK_XEXP_MODE} ${INK_I8:+-e INK_I8=$INK_I8} ${INK_DFLASH2:+-e INK_DFLASH2=$INK_DFLASH2} ${INK_F2_GTAU:+-e INK_F2_GTAU=$INK_F2_GTAU} ${INK_TP_PLAIN_N:+-e INK_TP_PLAIN_N=$INK_TP_PLAIN_N} ${INK_DENSE_ONEDNN:+-e INK_DENSE_ONEDNN=1} ${INK_ATT_SIMT:+-e INK_ATT_SIMT=1} ${GRIMOIRE_ONEDNN:+-e GRIMOIRE_ONEDNN=$GRIMOIRE_ONEDNN} $(env | grep -oE "^INK_[A-Z0-9_]+=[^ ]*" | sed "s/^/-e /" | tr "\n" " ") --entrypoint /bin/bash grimoire-b70:v1.10.10 \
  -c "cd /work/src && $WRAP ./bin/inkling2_gpu /inkling $ARGS" > /dev/null
t=0
while [ "$(docker inspect -f '{{.State.Running}}' ink-1123-$TAG 2>/dev/null)" = "true" ]; do
  sleep 5; t=$((t+5))
  if [ $t -ge 900 ]; then echo "STILL_RUNNING_AFTER_15MIN (not killed)"; exit 2; fi
done
mkdir -p logs; docker logs ink-1123-$TAG > logs/$TAG.log 2>&1; tail -40 logs/$TAG.log
echo "exit $(docker inspect -f '{{.State.ExitCode}}' ink-1123-$TAG) after ${t}s"
docker rm ink-1123-$TAG > /dev/null
echo "new 03:00.0 kernel lines: $(( $(dmesg | grep -c "$PCI") - before ))"
